interface.signature:
@GetMapping("/{customerId}")
public ResponseEntity<ApiResponse<CustomerResponse>> getCustomer(
  @PathVariable UUID customerId
) {
  CustomerResponse response = customerService.getCustomer(customerId);
  return ResponseEntity.ok(new ApiResponse<>(response, metadata));
}

public CustomerResponse getCustomer(UUID customerId) {
  Customer customer = customerRepository.findById(customerId)
    .orElseThrow(() -> new CustomerNotFoundException("Customer " + customerId + " not found"));

  auditService.createAuditEntry(Operation.READ, "CUSTOMER", customerId, user);

  return CustomerResponse.from(customer);
}
